  ('Q_20261115_08_37', 'PG', 'Prakarya 8', 'Jika tidak tersedia bahan finishing seperti varnish dan lem kayu, maka alternatif bahan finishsing yang dapat digunakan adalah....', 'none', '', '["lem kanji", "lem tembak", "lem lilin", "lem alteco"]'::jsonb, '[]'::jsonb, 'lem kanji', 10, 'Sesuai kunci jawaban.'),
