  ('Q_20261117_08_03', 'PG', 'Bahasa Indonesia SMP 8', 'Bagaimana bentuk daun bunga matahari berdasarkan teks?', 'none', '', '["Kecil dan bulat", "Lebar berbentuk hati", "Panjang dan runcing", "Tipis berbentuk jarum"]'::jsonb, '[]'::jsonb, 'Lebar berbentuk hati', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_04', 'PG', 'Bahasa Indonesia SMP 8', 'Mengapa bunga matahari membutuhkan cukup cahaya matahari?', 'none', '', '["Agar dapat tumbuh dengan baik", "Agar daunnya berubah warna", "Agar batangnya menjadi pendek", "Agar akarnya tidak tumbuh"]'::jsonb, '[]'::jsonb, 'Agar dapat tumbuh dengan baik', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_05', 'PG', 'Bahasa Indonesia SMP 8', 'Informasi yang sesuai dengan teks adalah ....<br>Teks 2 untuk soal nomor 6–10<br>Iklan Minuman Sehat<br>SEGARKAN HARIMU!<br>JUS BUAH ALAMI<br>Dibuat dari buah pilihan, tanpa tambahan pemanis buatan.<br>Sehat, Segar, dan Nikmat!<br>Ayo konsumsi buah setiap hari!', 'none', '', '["Bunga matahari hanya tumbuh di dalam ruangan.", "Biji bunga matahari dapat diolah menjadi kuaci.", "Bunga matahari memiliki bunga berwarna merah.", "Daun bunga matahari berbentuk panjang dan runcing."]'::jsonb, '[]'::jsonb, 'Biji bunga matahari dapat diolah menjadi kuaci.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_06', 'PG', 'Bahasa Indonesia SMP 8', 'Tujuan utama iklan tersebut adalah ....', 'none', '', '["Mengajak masyarakat mengonsumsi jus buah", "Memberitahukan cara menanam buah", "Menjelaskan proses pembuatan minuman", "Melaporkan hasil penelitian buah"]'::jsonb, '[]'::jsonb, 'Mengajak masyarakat mengonsumsi jus buah', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_07', 'PG', 'Bahasa Indonesia SMP 8', 'Kalimat yang menjadi slogan dalam iklan tersebut adalah ....', 'none', '', '["Dibuat dari buah pilihan", "Sehat, Segar, dan Nikmat!", "Ayo konsumsi buah setiap hari!", "Jus buah alami"]'::jsonb, '[]'::jsonb, 'Sehat, Segar, dan Nikmat!', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_08', 'PG', 'Bahasa Indonesia SMP 8', 'Keunggulan produk yang ditawarkan berdasarkan iklan adalah ....', 'none', '', '["Mengandung pewarna buatan", "Dibuat dari buah pilihan tanpa tambahan pemanis buatan", "Hanya tersedia dalam satu rasa", "Mengandung banyak bahan pengawet"]'::jsonb, '[]'::jsonb, 'Dibuat dari buah pilihan tanpa tambahan pemanis buatan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_09', 'PG', 'Bahasa Indonesia SMP 8', 'Sasaran utama iklan tersebut adalah ....', 'none', '', '["Orang yang ingin mengonsumsi minuman sehat", "Orang yang ingin membeli kendaraan", "Petani yang ingin menjual tanah", "Siswa yang ingin membeli buku"]'::jsonb, '[]'::jsonb, 'Orang yang ingin mengonsumsi minuman sehat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_10', 'PG', 'Bahasa Indonesia SMP 8', 'Jika iklan tersebut ingin dibuat lebih menarik, hal yang paling tepat dilakukan adalah ....<br>Teks 3 untuk soal nomor 11–15<br>Hutan Mangrove<br>Hutan mangrove merupakan ekosistem tumbuhan yang hidup di wilayah pesisir pantai. Tumbuhan mangrove memiliki akar yang khas dan mampu bertahan di lingkungan berlumpur serta air yang dipengaruhi pasang surut.<br>Hutan mangrove memiliki peran penting bagi lingkungan. Akar-akarnya dapat membantu mengurangi abrasi pantai dan menjadi tempat hidup berbagai jenis hewan, seperti ikan kecil, kepiting, dan udang.<br>Selain itu, hutan mangrove membantu menjaga keseimbangan ekosistem pesisir. Kerusakan hutan mangrove dapat menyebabkan berkurangnya habitat hewan dan meningkatnya risiko kerusakan pantai.', 'none', '', '["Menghilangkan nama produk", "Menggunakan gambar buah yang menarik dan informasi produk yang jelas", "Menggunakan tulisan yang sangat kecil", "Menghilangkan kalimat ajakan"]'::jsonb, '[]'::jsonb, 'Menggunakan gambar buah yang menarik dan informasi produk yang jelas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_11', 'PG', 'Bahasa Indonesia SMP 8', 'Hutan mangrove biasanya ditemukan di ....', 'none', '', '["Pegunungan tinggi", "Wilayah pesisir pantai", "Padang pasir", "Daerah perkotaan"]'::jsonb, '[]'::jsonb, 'Wilayah pesisir pantai', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_12', 'PG', 'Bahasa Indonesia SMP 8', 'Fungsi akar mangrove berdasarkan teks adalah ....', 'none', '', '["Menghasilkan buah yang manis", "Membantu mengurangi abrasi pantai", "Mengubah air laut menjadi air tawar", "Menghasilkan oksigen paling banyak di dunia"]'::jsonb, '[]'::jsonb, 'Membantu mengurangi abrasi pantai', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_13', 'PG', 'Bahasa Indonesia SMP 8', 'Hewan yang dapat hidup di kawasan hutan mangrove adalah ....', 'none', '', '["Harimau dan gajah", "Kambing dan sapi", "Ikan kecil, kepiting, dan udang", "Unta dan kuda"]'::jsonb, '[]'::jsonb, 'Ikan kecil, kepiting, dan udang', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_14', 'PG', 'Bahasa Indonesia SMP 8', 'Apa kemungkinan yang terjadi jika hutan mangrove mengalami kerusakan?', 'none', '', '["Habitat hewan semakin bertambah", "Risiko kerusakan pantai meningkat", "Air laut menjadi lebih jernih", "Semua hewan berpindah ke pegunungan"]'::jsonb, '[]'::jsonb, 'Risiko kerusakan pantai meningkat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_08_15', 'PG', 'Bahasa Indonesia SMP 8', 'Gagasan utama paragraf kedua adalah ....<br>Teks 4 untuk soal nomor 16–20', 'image', './assets/soal/soal-0043.jpg', '["Bentuk akar tumbuhan mangrove", "Jenis tanah di wilayah pesisir", "Peran hutan mangrove bagi lingkungan", "Cara menanam pohon mangrove"]'::jsonb, '[]'::jsonb, 'Peran hutan mangrove bagi lingkungan', 10, 'Sesuai kunci jawaban.'),
