  ('Q_20261117_08_18', 'PG', 'Bahasa Indonesia SMP 8', 'Mengapa masyarakat perlu menghemat air?', 'none', '', '["Karena air tidak memiliki manfaat", "Karena air merupakan sumber daya yang perlu dijaga", "Karena air hanya digunakan untuk mandi", "Karena air dapat dibuat kapan saja tanpa batas"]'::jsonb, '[]'::jsonb, 'Karena air merupakan sumber daya yang perlu dijaga', 10, 'Sesuai kunci jawaban.'),
